  surfaceHover: '#F5F5F5',   // Light gray for hover
  
  // Text Colors
  textPrimary: '#1A1A1A',    // Deep charcoal
  textSecondary: '#666666',  // Medium gray
  textTertiary: '#999999',   // Light gray
  textMuted: '#CCCCCC',      // Very light gray
  
