import React, { useMemo } from 'react';
import { Card, Statistic, Row, Col, Typography } from 'antd';
import { TrophyOutlined, StarOutlined } from '@ant-design/icons';
import styled from 'styled-components';

const { Title } = Typography;

const StatsContainer = styled.div`
  margin-bottom: 24px;
`;

const StatCard = styled(Card)`
  background: #FFFFFF;
  border: 1px solid rgba(26, 26, 26, 0.08);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(26, 26, 26, 0.08);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  
  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 32px rgba(26, 26, 26, 0.12);
    border-color: rgba(26, 26, 26, 0.12);
  }
`;

const Stats = ({ albums, loading }) => {
  const stats = useMemo(() => {
    if (!albums || albums.length === 0) {
      return { total: 0, bestNew: 0 };
    }
    
    return {
      total: albums.length,
      bestNew: albums.filter(album => album.best_new).length,
    };
  }, [albums]);

  if (loading) {
    return null;
  }

  return (
    <StatsContainer>
      <Row gutter={[16, 16]}>
        <Col xs={24} sm={12}>
          <StatCard>
            <Statistic
              title="High-Scoring Albums"
              value={stats.total}
              prefix={<StarOutlined style={{ color: '#E63946' }} />}
              valueStyle={{ color: '#E63946', fontSize: '2rem', fontWeight: 700 }}
            />
          </StatCard>
        </Col>
        <Col xs={24} sm={12}>
          <StatCard>
            <Statistic
              title="Best New Selections"
              value={stats.bestNew}
              prefix={<TrophyOutlined style={{ color: '#FFD60A' }} />}
              valueStyle={{ color: '#FFD60A', fontSize: '2rem', fontWeight: 700 }}
            />
          </StatCard>
        </Col>
      </Row>
    </StatsContainer>
  );
};

export default Stats;

